import os
import sys

print("CWD:", os.getcwd())

for root, dirs, files in os.walk("."):
    # skip hidden dirs like .codex
    dirs[:] = [d for d in dirs if not d.startswith(".")]
    depth = root.count(os.sep)
    if depth <= 3:
        for f in sorted(files):
            if f.lower().endswith(".pdf") or root == ".":
                full = os.path.join(root, f)
                try:
                    size = os.path.getsize(full)
                except OSError as e:
                    size = f"err:{e}"
                print(f"{full}  size={size}")

if not os.path.exists("report.pdf"):
    print("NOTE: report.pdf not found in CWD")
    sys.exit(0)

try:
    from pypdf import PdfReader
    reader = PdfReader("report.pdf")
    print("report.pdf pages:", len(reader.pages))
    print("report.pdf metadata:", reader.metadata)
except Exception as e:
    print("pypdf read error:", type(e).__name__, e)
